{"results": [{"id": "hp_doc_b7b8a4bbb6131f918981ea30471640905b0ccaa1a941d460dfda9bd215c89f5f", "title": "PGA National Golf Club", "text": "PGA National Golf Club, the home of the Professional Golfers' Association of America, is in the southeastern United States, located at the PGA National Resort & Spa in Palm Beach Gardens, Florida. The golf facilities include five championship 18-hole courses, four within the main resort ground and another 5 mi west. The resort was acquired in August 2006 by Century Golf Partners in conjunction with Walton Street Capital, LLC and SCS Advisors, Inc.", "score": 54.2759}, {"id": "hp_doc_7222f07675cdb06b26b85b441c2414e5b98bb9169e8b72da86c29de5ff3d5070", "title": "PGA National Champion Course", "text": "The PGA National Champion Course is an 18-hole golf course located in Palm Beach Gardens, Florida, USA.", "score": 46.1349}, {"id": "hp_doc_c427748353e1c4d27703990d71c671b07e26fe47a72fbeb14d42ba4792098639", "title": "1971 PGA Championship", "text": "The 1971 PGA Championship was the 53rd PGA Championship, played February 25–28 at the original PGA National Golf Club, presently known as BallenIsles Country Club (East Course) in Palm Beach Gardens, Florida.", "score": 43.3987}], "remaining_searches": 2}
