{"results": [{"id": "hp_doc_d22e38318fa2dd7ca51f5ea0a98e436ce428299cf8d9f79fcb0b649bf9c9fa92", "title": "Palm Beach Gardens, Florida", "text": "Palm Beach Gardens is a city in Palm Beach County in the U.S. state of Florida. As of the 2010 United States Census , the population was 48,452. The city has a number of gated communities.", "score": 39.9681}, {"id": "hp_doc_53081399650a791861d91d39844178a625ec779d6fe94d4b93e05c783a03f10b", "title": "North Palm Beach County General Aviation Airport", "text": "North Palm Beach County Airport (FAA LID: F45) , also known as North County Airport, is an uncontrolled general aviation airport located 12 nautical miles (22 km) northwest of West Palm Beach off the Bee Line Highway in Palm Beach Gardens, Florida. The airport is owned by Palm Beach County and operated by the Palm Beach County Airports Department.", "score": 38.4436}, {"id": "hp_doc_a42f426cf129fcdbbcb7d43efd2ab52f0616e66a5027b5efcf4c1fd980e25424", "title": "2004 Palm Beach Gardens Challenger", "text": "The 2004 Palm Beach Gardens Challenger was a women's professional tennis tournament played on clay courts. It was the 2nd edition of the Palm Beach Gardens Challenger, and was an ITF $50,000 tournament from 2003–2005. It took place at the Palm Beach Gardens Tennis Center in Florida from November 29 to Dec 5, 2004.", "score": 34.5759}], "remaining_searches": 1}
